const repo=path.resolve(process.argv[2]),out=path.resolve(process.argv[3]),url=p=>pathToFileURL(path.join(repo,p)),head='55cafc255caa4d361a5d8ce3b2d6081a49a1ba3c',sha=b=>crypto.createHash('sha256').update(b).digest('hex'),hash=v=>sha(JSON.stringify(v));assert.equal(execFileSync('git',['rev-parse','HEAD'],{cwd:repo,encoding:'utf8'}).trim(),head);assert.equal(fs.existsSync(out),false);
